import {discoverInventory,validateInventory,sourceHash} from '../scripts/quality-inventory';
const root='.planning/memory-resilience/',read=(p:string)=>JSON.parse(readFileSync(p,'utf8')),text=(p:string)=>readFileSync(p,'utf8'),save=(p:string,v:unknown)=>writeFileSync(p,JSON.stringify(v,null,2)+'\n');
const current=read('.git/q100-state-compat.json'),native=read('.git/q100-state-native.json'),measure=read('.git/q100-state-measure.json'),faults=read('.git/q100-state-faults.json');
for(const proof of [current,native,measure,faults])for(const row of proof.sourceInputs)assert.equal(sourceHash(text(row.path)),row.sourceHash,row.path);
assert.deepEqual(current.sourceInputs,native.sourceInputs);
for(const run of [current,...native.runs]){assert.equal(run.exit,0);assert(run.output.includes('433 pass')&&run.output.includes('0 fail')&&run.output.includes('3203 expect()'));}
assert.equal(native.crossRuntimeProof.exit,0);assert.equal(measure.runs[0].exit,0);assert.equal(faults.runs.length,9);assert.equal(faults.runs[0].exit,0);
for(const run of faults.runs.slice(1)){assert.equal(run.exit,1);assert(run.output.includes('(fail)'));}
assert.equal(text('.git/q100-state-test-types.txt').trim(),'');assert(text('.git/q100-state-isolation.txt').includes('PASS (no violations)'));
assert(text('.git/q100-state-red.txt').includes('15 fail'));assert(text('.git/q100-state-fts-red.txt').includes('Received promise that resolved'));
const ledger=read(root+'work-items.json'),get=(id:string)=>ledger.items.find((i:any)=>i.id===id),evidence=root+'evidence/Q100.4.1.json';assert.equal(get('Q100.4.1').status,'active');
get('Q100.4.1').status='verified';get('Q100.4.1').evidence.push(evidence);get('Q100.4.1').progress={status:'Scoped conservative automatic admission verified; caller adoption and full quality remain mandatory.',testsPerRuntime:433,assertionsPerRuntime:3203,testFiles:17,decisionFaultsDetected:8,crossRuntimeReceipt:'Bun1.4.1 writes;1.3.14 admits wide integer and adjacent real inputs.'};
get('Q100.4.2').status='active';ledger.current_item='Q100.4.2';get('Q100.4.2').evidence.push(evidence);get('Q100.4.2').progress={next:'Reproduce retained-event retry through real extraction/remote sync with no new source/candidates. First account for governance and dreaming event-backed direct repository writes using a transactional checkpoint protocol or verified reconciliation; do not bless unrelated divergence.',constraints:'Automatic mode is not wired into actual callers. Preserve unlogged/imported data and direct deletions; old receipts require reconciliation. Source freshness is not projection/index health. Measure fingerprint cost.',owner:'memory-nexus',trigger:'Before Q100.4/Q100/B11.74.7/B10/R02 acceptance.'};
get('Q100.4').evidence.push(evidence);get('Q100.4').progress={status:'Q100.4.1 scoped verified; Q100.4.2 active; Q100.4.3 mandatory quality remains.',owner:'memory-nexus'};
get('Q100.4.3').observed_gap='New state module diagnoses100%; driver zero branch denominator requires final applicability review. Changed event-log/source/replacement full metrics, cleanup and mode admission, fingerprint cost and supported-platform proof remain mandatory.';
get('R04').progress.projectionContentNotice={document:'docs/plans/2026-09-28-projection-replay-execution.md',owner:'memory-nexus',trigger:'Before caller adoption: communicate projectionState receipt field, old receipt reconciliation and event-backed direct writer compatibility; no DDL migration or data cutover.'};
const catalog=discoverInventory(process.cwd()),manifest=read(root+'quality-classifications.json');assert.equal(catalog.files.length,477);
for(const measured of measure.measurement.files){const path=measured.path,file=catalog.files.find(f=>f.path===path)!;let row=manifest.files.find((r:any)=>r.path===path);if(!row){row={path,package:file.package,tier:'S',rationale:'Projection content identity, destructive automatic admission and native safety driver.',applicability:{mode:'measure',reason:'Executable Tier S; no exclusion approved.'},decisionStatus:'proposed - independent review pending'};manifest.files.push(row);}row.sourceHash=file.sourceHash;row.inspection={sourceRevision:'57fb7b9 + current source hash',anchor:'Q100.4.1 automatic replay authority',scope:'Paired native/cross-runtime proof; actual callers and full quality remain mandatory.'};row.metricApplicability={status:'diagnostic - final Q100.4.3 acceptance pending',sourceHash:file.sourceHash,evidence,metrics:Object.fromEntries(Object.entries(measured.metrics).map(([name,value]:[string,any])=>[name,{observedCounterTotal:value.total,proposal:value.total===0?'Review zero denominator and instrumenter completeness':'measure - completeness unverified'}]))};}
for(const file of measure.measurement.files.filter((f:any)=>f.path.includes('projection-state')))for(const metric of Object.values(file.metrics) as any[])assert.equal(metric.pct,100);
manifest.files.sort((a:any,b:any)=>a.path.localeCompare(b.path));assert.deepEqual(validateInventory(catalog,manifest),[]);
const items=new Map<string,any>(ledger.items.map((i:any)=>[i.id,i])),done=new Set<string>();function visit(id:string,stack=new Set<string>()){assert(items.has(id)&&!stack.has(id));if(done.has(id))return;for(const dep of items.get(id).depends_on)visit(dep,new Set([...stack,id]));done.add(id);}for(const id of items.keys())visit(id);assert.equal(items.size,255);assert.deepEqual(ledger.items.filter((i:any)=>i.status==='active').map((i:any)=>i.id),['Q100.4.2']);
const free=statfsSync(process.cwd());
save(evidence,{item_id:'Q100.4.1',status:'verified - scoped replay authority only',recordedAt:new Date().toISOString(),cwd:process.cwd(),startingRevision:'57fb7b932335b0ba1311568d80b905ffbf23491b',sourceInputs:current.sourceInputs,current,native,diagnosticCoverage:measure,decisionChecks:faults,
