 contract:['Fingerprint six tables, columns and typed values in bounded-memory native snapshot; int64/real precision, NULL/NUL and blob/text distinctions tested.','Content identity commits with source receipt; content/FTS receipt-trigger side effects roll back; retry works.','Automatic admission requires matching content or empty bootstrap. Unlogged/direct/imported/deleted divergence and old fingerprints require explicit reconciliation.'],
 limits:['Actual callers remain unwired. Governance/dreaming direct event-backed writes need Q100.4.2 checkpoint/reconciliation before adoption, without blessing unrelated divergence.','Fingerprint is linear in projected rows, not index health or source/cutover authority. No DDL migration.','State module diagnoses100%; driver zero-branch denominator, full package/changed-line/instrumenter/platform/review and cleanup remain Q100.4.3. No installed/two-machine acceptance.','Only owned synthetic/runtime fixtures; no canonical data/models/providers/hooks/replication/worktrees/blocked cleanup touched. Owned temporary containers cleaned.'],
 disk:{freeBytes:free.bavail*free.bsize},validation:{catalogFiles:477,packages:catalog.packages.length,ledgerItems:255,acyclic:true,source:text('.git/q100-state-checkpoint.ts')}});
save(root+'executable-catalog.json',catalog);save(root+'quality-classifications.json',manifest);save(root+'work-items.json',ledger);console.log('Q100.4.1 scoped verified;Q100.4.2 active;477 files,255 acyclic items; free GiB '+(free.bavail*free.bsize/2**30).toFixed(2));
